119: async fn exercise_completed_recovery(
120:     planned: bool,
121:     activation_outcome: Option<bool>,
122:     inspect_completion: bool,
123: ) {
124:     let CompletionFixture {
125:         live:
126:             RoutePublicationFixture {
127:                 fixture: f,
128:                 database: db,
129:                 request,
130:             },
131:         attestation,
132:         complete_phase,
133:         completed,
134:         outcome,
135:     } = {
136:         let prepared = Box::pin(prepare_completion(planned, inspect_completion));
137:         prepared.await
138:     };
139:     // The preparation poll frame has returned before resolving the original
140:     // completion. Keep the same live owners, signed fact, phase, and deadlines.
141:     let id = request.operation_id;
142:     if inspect_completion {
143:         Box::pin(resolve_expired_completion(
144:             &f,
145:             &db,
146:             id,
147:             complete_phase,
148:             completed,
149:             &attestation,
150:         ))
151:         .await;
152:     } else {
153:         Box::pin(resolve_phase(&f, id, complete_phase, outcome)).await;
154:     }
155:     let route = {
156:         let completed = Box::pin(complete_recovery(
157:             RoutePublicationFixture {
158:                 fixture: f,
159:                 database: db,
160:                 request,
161:             },
162:             attestation,
163:             planned,
164:             activation_outcome,
165:         ));
166:         completed.await
167:     };
168:     if let Some(RoutePublicationFixture {
169:         mut fixture,
170:         database,
171:         request,
172:     }) = route
173:     {
174:         // The old future and its poll frame are gone; this moves the same
175:         // storage owners and original request into the next phase. No detached
176:         // task, replacement authorization or altered deadline is introduced.
177:         Box::pin(exercise_route_publication(&mut fixture, database, &request)).await;
178:     }
179: }
