243: #[async_trait::async_trait]
244: impl RaftTransport for BootstrapVoteProbe {
245:     async fn send(
246:         &self,
247:         group: &str,
248:         source: u64,
249:         target: u64,
250:         node: &BasicNode,
251:         request: RpcRequest,
252:     ) -> anyhow::Result<RpcResponse> {
253:         let mut guard = match &request {
254:             RpcRequest::Vote(vote) => Some(self.begin(source, target, vote)),
255:             _ => None,
256:         };
257:         let result = self.router.send(group, source, target, node, request).await;
258:         if let Some(guard) = &mut guard {
259:             let outcome = match &result {
260:                 Ok(RpcResponse::Vote(Ok(response))) => Outcome::ReturnedVote(response.clone()),
261:                 Ok(RpcResponse::Vote(Err(error))) => {
262:                     Outcome::ReturnedRaftError(ErrorText::capture(error))
263:                 }
264:                 Ok(_) => Outcome::ReturnedUnexpectedResponse,
265:                 Err(error) => Outcome::ReturnedTransportError(ErrorText::capture(error)),
266:             };
267:             guard.finish(outcome, true);
268:         }
269:         result
270:     }
271: }
